#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <immintrin.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 120
#define NC 1024
#define MAX_THREADS 256

/* ---------- thread count: physical cores only ---------- */

static int g_nthreads = 0;

static int detect_physical_cores(void)
{
    long nlog = sysconf(_SC_NPROCESSORS_ONLN);
    if (nlog < 1) nlog = 1;
    int phys = 0, ok = 0;
    for (int cpu = 0; cpu < 4096 && cpu < nlog * 4; cpu++) {
        char path[128];
        snprintf(path, sizeof path,
                 "/sys/devices/system/cpu/cpu%d/topology/thread_siblings_list", cpu);
        FILE *f = fopen(path, "r");
        if (!f) continue;
        int first = -1;
        if (fscanf(f, "%d", &first) == 1) {
            ok = 1;
            if (first == cpu) phys++;
        }
        fclose(f);
    }
    if (!ok || phys < 1) phys = (int)nlog;
    if (phys > MAX_THREADS) phys = MAX_THREADS;
    return phys;
}

/* ---------- persistent per-thread packing buffers ---------- */

static float *g_abuf[MAX_THREADS];
static float *g_bbuf[MAX_THREADS];

static void ensure_buffers(int t)
{
    if (!g_abuf[t])
        g_abuf[t] = (float *)aligned_alloc(64, sizeof(float) * MC * KC);
    if (!g_bbuf[t])
        g_bbuf[t] = (float *)aligned_alloc(64, sizeof(float) * KC * NC);
}

/* ---------- packing ---------- */

static void pack_A(const float *A, int n, int i0, int mc, int p0, int kc, float *Ap)
{
    for (int ir = 0; ir < mc; ir += MR) {
        int mr = mc - ir < MR ? mc - ir : MR;
        const float *src = A + (size_t)(i0 + ir) * n + p0;
        if (mr == MR) {
            const float *r0 = src, *r1 = src + n, *r2 = src + 2 * (size_t)n;
            const float *r3 = src + 3 * (size_t)n, *r4 = src + 4 * (size_t)n, *r5 = src + 5 * (size_t)n;
            for (int p = 0; p < kc; p++) {
                Ap[0] = r0[p]; Ap[1] = r1[p]; Ap[2] = r2[p];
                Ap[3] = r3[p]; Ap[4] = r4[p]; Ap[5] = r5[p];
                Ap += MR;
            }
        } else {
            for (int p = 0; p < kc; p++) {
                int r = 0;
                for (; r < mr; r++) Ap[r] = src[(size_t)r * n + p];
                for (; r < MR; r++) Ap[r] = 0.0f;
                Ap += MR;
            }
        }
    }
}

static void pack_B(const float *B, int n, int p0, int kc, int j0, int nc, float *Bp)
{
    for (int jr = 0; jr < nc; jr += NR) {
        int nr = nc - jr < NR ? nc - jr : NR;
        const float *src = B + (size_t)p0 * n + j0 + jr;
        if (nr == NR) {
            for (int p = 0; p < kc; p++) {
#ifdef __AVX2__
                _mm256_store_ps(Bp, _mm256_loadu_ps(src));
                _mm256_store_ps(Bp + 8, _mm256_loadu_ps(src + 8));
#else
                memcpy(Bp, src, NR * sizeof(float));
#endif
                src += n;
                Bp += NR;
            }
        } else {
            for (int p = 0; p < kc; p++) {
                int j = 0;
                for (; j < nr; j++) Bp[j] = src[j];
                for (; j < NR; j++) Bp[j] = 0.0f;
                src += n;
                Bp += NR;
            }
        }
    }
}

/* ---------- micro-kernel: 6x16 ---------- */

static void kernel_6x16(int kc, const float *a, const float *b,
                        float *c, int ldc, int accumulate)
{
#ifdef __AVX2__
    __m256 c00 = _mm256_setzero_ps(), c01 = _mm256_setzero_ps();
    __m256 c10 = _mm256_setzero_ps(), c11 = _mm256_setzero_ps();
    __m256 c20 = _mm256_setzero_ps(), c21 = _mm256_setzero_ps();
    __m256 c30 = _mm256_setzero_ps(), c31 = _mm256_setzero_ps();
    __m256 c40 = _mm256_setzero_ps(), c41 = _mm256_setzero_ps();
    __m256 c50 = _mm256_setzero_ps(), c51 = _mm256_setzero_ps();

    for (int p = 0; p < kc; p++) {
        __m256 b0 = _mm256_load_ps(b);
        __m256 b1 = _mm256_load_ps(b + 8);
        __m256 a0;
        a0 = _mm256_broadcast_ss(a + 0);
        c00 = _mm256_fmadd_ps(a0, b0, c00); c01 = _mm256_fmadd_ps(a0, b1, c01);
        a0 = _mm256_broadcast_ss(a + 1);
        c10 = _mm256_fmadd_ps(a0, b0, c10); c11 = _mm256_fmadd_ps(a0, b1, c11);
        a0 = _mm256_broadcast_ss(a + 2);
        c20 = _mm256_fmadd_ps(a0, b0, c20); c21 = _mm256_fmadd_ps(a0, b1, c21);
        a0 = _mm256_broadcast_ss(a + 3);
        c30 = _mm256_fmadd_ps(a0, b0, c30); c31 = _mm256_fmadd_ps(a0, b1, c31);
        a0 = _mm256_broadcast_ss(a + 4);
        c40 = _mm256_fmadd_ps(a0, b0, c40); c41 = _mm256_fmadd_ps(a0, b1, c41);
        a0 = _mm256_broadcast_ss(a + 5);
        c50 = _mm256_fmadd_ps(a0, b0, c50); c51 = _mm256_fmadd_ps(a0, b1, c51);
        a += MR;
        b += NR;
    }

#define STORE_ROW(r, x0, x1)                                                   \
    do {                                                                       \
        float *cr = c + (size_t)(r) * ldc;                                     \
        if (accumulate) {                                                      \
            x0 = _mm256_add_ps(x0, _mm256_loadu_ps(cr));                       \
            x1 = _mm256_add_ps(x1, _mm256_loadu_ps(cr + 8));                   \
        }                                                                      \
        _mm256_storeu_ps(cr, x0);                                              \
        _mm256_storeu_ps(cr + 8, x1);                                          \
    } while (0)
    STORE_ROW(0, c00, c01);
    STORE_ROW(1, c10, c11);
    STORE_ROW(2, c20, c21);
    STORE_ROW(3, c30, c31);
    STORE_ROW(4, c40, c41);
    STORE_ROW(5, c50, c51);
#undef STORE_ROW
#else
    float acc[MR][NR];
    memset(acc, 0, sizeof acc);
    for (int p = 0; p < kc; p++) {
        for (int r = 0; r < MR; r++)
            for (int j = 0; j < NR; j++)
                acc[r][j] += a[r] * b[j];
        a += MR;
        b += NR;
    }
    for (int r = 0; r < MR; r++)
        for (int j = 0; j < NR; j++)
            c[(size_t)r * ldc + j] = accumulate ? c[(size_t)r * ldc + j] + acc[r][j] : acc[r][j];
#endif
}

/* ---------- macro-kernel ---------- */

static void macro_kernel(int mc, int nc, int kc, const float *Ap, const float *Bp,
                         float *C, int ldc, int accumulate)
{
    for (int jr = 0; jr < nc; jr += NR) {
        int nr = nc - jr < NR ? nc - jr : NR;
        const float *bp = Bp + (size_t)jr * kc;
        for (int ir = 0; ir < mc; ir += MR) {
            int mr = mc - ir < MR ? mc - ir : MR;
            const float *ap = Ap + (size_t)ir * kc;
            float *cp = C + (size_t)ir * ldc + jr;
            if (mr == MR && nr == NR) {
                kernel_6x16(kc, ap, bp, cp, ldc, accumulate);
            } else {
                float tmp[MR * NR] __attribute__((aligned(64)));
                kernel_6x16(kc, ap, bp, tmp, NR, 0);
                for (int r = 0; r < mr; r++)
                    for (int j = 0; j < nr; j++)
                        cp[(size_t)r * ldc + j] = accumulate
                            ? cp[(size_t)r * ldc + j] + tmp[r * NR + j]
                            : tmp[r * NR + j];
            }
        }
    }
}

/* ---------- per-thread driver ---------- */

typedef struct {
    const float *A, *B;
    float *C;
    int n, row0, row1, tid;
} job_t;

static void *worker(void *arg)
{
    job_t *jb = (job_t *)arg;
    const float *A = jb->A, *B = jb->B;
    float *C = jb->C;
    int n = jb->n, row0 = jb->row0, row1 = jb->row1;
    float *Ap = g_abuf[jb->tid];
    float *Bp = g_bbuf[jb->tid];

    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            pack_B(B, n, pc, kc, jc, nc, Bp);
            for (int ic = row0; ic < row1; ic += MC) {
                int mc = row1 - ic < MC ? row1 - ic : MC;
                pack_A(A, n, ic, mc, pc, kc, Ap);
                macro_kernel(mc, nc, kc, Ap, Bp, C + (size_t)ic * n + jc, n, pc != 0);
            }
        }
    }
    return NULL;
}

/* ---------- entry point ---------- */

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (g_nthreads == 0) g_nthreads = detect_physical_cores();

    int panels = (n + MR - 1) / MR;
    int nt = g_nthreads;
    if ((long)n * n * n < 64L * 64 * 64) nt = 1;
    if (nt > panels) nt = panels;
    if (nt < 1) nt = 1;

    int per = (panels + nt - 1) / nt;          /* micro-panels per thread */
    nt = (panels + per - 1) / per;

    job_t jobs[MAX_THREADS];
    pthread_t th[MAX_THREADS];

    for (int t = 0; t < nt; t++) {
        ensure_buffers(t);
        int r0 = t * per * MR;
        int r1 = r0 + per * MR;
        if (r1 > n) r1 = n;
        jobs[t].A = A; jobs[t].B = B; jobs[t].C = C;
        jobs[t].n = n; jobs[t].row0 = r0; jobs[t].row1 = r1; jobs[t].tid = t;
    }

    int created[MAX_THREADS] = {0};
    for (int t = 1; t < nt; t++)
        created[t] = pthread_create(&th[t], NULL, worker, &jobs[t]) == 0;
    worker(&jobs[0]);
    for (int t = 1; t < nt; t++) {
        if (created[t]) pthread_join(th[t], NULL);
        else worker(&jobs[t]);   /* fallback if thread creation failed */
    }
}
